<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/src/helpers.php';
$user=require_admin(); $period=$_GET['period']??'month'; $from=$_GET['from']??''; $to=$_GET['to']??'';
if($period==='today'){$from=$to=date('Y-m-d');}elseif($period==='week'){$from=date('Y-m-d',strtotime('monday this week'));$to=date('Y-m-d');}elseif($period==='month'){$from=date('Y-m-01');$to=date('Y-m-d');}elseif(!DateTimeImmutable::createFromFormat('!Y-m-d',$from)||!DateTimeImmutable::createFromFormat('!Y-m-d',$to)||$from>$to){$period='month';$from=date('Y-m-01');$to=date('Y-m-d');}
$s=db()->prepare("SELECT (SELECT COUNT(*) FROM users WHERE role='employee' AND active=1) active_mrs,(SELECT COUNT(*) FROM visits WHERE DATE(visited_at) BETWEEN ? AND ?) visits,(SELECT COUNT(*) FROM visits WHERE status='converted' AND DATE(visited_at) BETWEEN ? AND ?) converted,(SELECT COUNT(*) FROM orders WHERE order_date BETWEEN ? AND ?) orders,(SELECT COALESCE(SUM(amount),0) FROM orders WHERE order_date BETWEEN ? AND ?) sales");$s->execute([$from,$to,$from,$to,$from,$to,$from,$to]);$stats=$s->fetch();
$mr=db()->prepare("SELECT u.id,u.name,u.mobile,u.active,(SELECT COUNT(*) FROM visits v WHERE v.mr_id=u.id AND DATE(v.visited_at) BETWEEN ? AND ?) visits,(SELECT COALESCE(SUM(o.amount),0) FROM orders o WHERE o.mr_id=u.id AND o.order_date BETWEEN ? AND ?) sales FROM users u WHERE u.role='employee' ORDER BY sales DESC,visits DESC,u.name");$mr->execute([$from,$to,$from,$to]);$mrs=$mr->fetchAll();
$v=db()->prepare("SELECT v.*,p.name party_name,p.area,u.name mr_name FROM visits v JOIN parties p ON p.id=v.party_id JOIN users u ON u.id=v.mr_id WHERE DATE(v.visited_at) BETWEEN ? AND ? ORDER BY v.visited_at DESC LIMIT 12");$v->execute([$from,$to]);$visits=$v->fetchAll();
$o=db()->prepare("SELECT o.*,p.name party_name,u.name mr_name FROM orders o JOIN parties p ON p.id=o.party_id JOIN users u ON u.id=o.mr_id WHERE o.order_date BETWEEN ? AND ? ORDER BY o.order_date DESC,o.id DESC LIMIT 10");$o->execute([$from,$to]);$orders=$o->fetchAll();
function admin_map_url(float $lat,float $lng):string{return 'https://www.google.com/maps?q='.rawurlencode($lat.','.$lng);}
page_start('Admin dashboard',$user);
?>
<form method="get" class="card"><div class="quick-filters"><a href="index.php?period=today">Today</a><a href="index.php?period=week">This week</a><a href="index.php?period=month">This month</a></div><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><button>Show custom range</button></form>
<section class="metric-grid"><article class="card metric"><strong><?=e((string)$stats['active_mrs'])?></strong><span>Active MRs</span></article><article class="card metric"><strong><?=e((string)$stats['visits'])?></strong><span>Visits</span></article><article class="card metric"><strong>₹<?=number_format((float)$stats['sales'],0)?></strong><span>Gross sales</span></article><article class="card metric"><strong><?=e((string)$stats['orders'])?></strong><span>Orders</span></article></section>
<section class="card"><strong><?=e((string)$stats['converted'])?> converted visits</strong><p class="muted"><?=e(date('d M Y',strtotime($from)))?> to <?=e(date('d M Y',strtotime($to)))?> · <a href="report.php?from=<?=e($from)?>&to=<?=e($to)?>">Open complete report</a></p></section>
<h2>MR performance</h2><?php foreach($mrs as $row):?><a class="card party-card" href="report.php?from=<?=e($from)?>&to=<?=e($to)?>&mr_id=<?=$row['id']?>"><div class="row"><strong><?=e($row['name'])?></strong><strong>₹<?=number_format((float)$row['sales'],2)?></strong></div><span><?=e($row['mobile'])?> · <?=e((string)$row['visits'])?> visits · <?=$row['active']?'Active':'Inactive'?></span></a><?php endforeach;?><?php if(!$mrs):?><p class="muted">No MRs available.</p><?php endif;?>
<h2>Latest field updates</h2><?php foreach($visits as $visit):?><article class="card small"><div class="row"><strong><?=e($visit['party_name'])?></strong><span class="badge <?=$visit['status']==='converted'?'green':'grey'?>"><?=e(str_replace('_',' ',$visit['status']))?></span></div><p><?=e($visit['mr_name'])?> · <?=e(date('d M, g:i a',strtotime($visit['visited_at'])))?> · <?=e($visit['area'])?></p><p><?=e($visit['remark'])?:'No remark'?></p><p><a target="_blank" rel="noopener" href="<?=e(admin_map_url((float)$visit['latitude'],(float)$visit['longitude']))?>">View captured location</a></p><?php if($visit['photo_path']):?><a href="../photo.php?id=<?=$visit['id']?>" target="_blank"><img class="visit-photo" src="../photo.php?id=<?=$visit['id']?>" alt="Visit proof photo"></a><?php endif;?></article><?php endforeach;?><?php if(!$visits):?><p class="muted">No field updates in this period.</p><?php endif;?>
<h2>Latest orders</h2><?php foreach($orders as $order):?><article class="card small"><div class="row"><strong><?=e($order['party_name'])?></strong><strong>₹<?=number_format((float)$order['amount'],2)?></strong></div><p><?=e($order['mr_name'])?> · <?=e($order['product'])?> · Qty <?=e((string)$order['quantity'])?> · <?=e(date('d M Y',strtotime($order['order_date'])))?></p></article><?php endforeach;?><?php if(!$orders):?><p class="muted">No orders in this period.</p><?php endif;?>
<?php page_end($user); ?>
